<script setup>defineProps({ src: { type: String, required: true }, alt: { type: String, default: "" }, kind: { type: String, default: "image" }, poster: { type: String, default: "" }, caption: { type: String, default: "" }, aspect: { type: String, default: "16 / 9" }, fit: { type: String, default: "cover" }, position: { type: String, default: "50% 50%" }, loading: { type: String, default: "lazy" }, autoplay: { type: Boolean, default: false }, controls: { type: Boolean, default: true }, muted: { type: Boolean, default: true } })</script>
<template><figure class="system-media" :style="{ '--system-media-aspect': aspect, '--system-media-fit': fit, '--system-media-position': position }"><div class="system-media__frame"><video v-if="kind === 'video'" class="system-media__asset" :src="src" :poster="poster || undefined" :autoplay="autoplay" :controls="controls" :muted="muted" :aria-label="alt || undefined" playsinline><slot name="track" /></video><img v-else class="system-media__asset" :src="src" :alt="alt" :loading="loading" decoding="async" /><slot name="overlay" /></div><figcaption v-if="caption || $slots.caption" class="system-media__caption"><slot name="caption">{{ caption }}</slot></figcaption></figure></template>
<style scoped>.system-media{display:grid;gap:var(--spacing-2xs);margin:0}.system-media__frame{position:relative;overflow:hidden;isolation:isolate;aspect-ratio:var(--system-media-aspect);border-radius:var(--component-radius-block);background:var(--theme-surface)}.system-media__asset{display:block;width:100%;height:100%;object-fit:var(--system-media-fit);object-position:var(--system-media-position)}.system-media__caption{max-width:65ch;color:var(--theme-text-muted);font-size:var(--font-size--1);line-height:var(--font-line-height-4)}@media (prefers-reduced-motion:reduce){.system-media__asset{animation:none!important;transition:none!important}}</style>
